  private books: Book[] = [];

  getAll(): Book[] {
    return this.books;
  }
}

class Helper {
  static formatTitle(title: string): string {
    return title.trim();
  }
}

export function formatBook(b: Book): string {
  return Helper.formatTitle(b.title);
}

